import sys
from collections import deque

def main():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    n = int(data[0])
    f = int(data[1])

    grid = [list(row) for row in data[2:2 + n]]

    if int(grid[0][0]) <= f:
        grid[0][0] = '*'
        queue = deque([(0, 0)])

        while queue:
            r, c = queue.popleft()

            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    val = grid[nr][nc]
                    if val != '*' and int(val) <= f:
                        grid[nr][nc] = '*'
                        queue.append((nr, nc))

    sys.stdout.write('\n'.join(''.join(row) for row in grid) + '\n')

if __name__ == '__main__':
    main()
